=== Method: calc (AbstractMethod) ===
/* The purpose of this class is to determine the brake request release gradient for a standard drie off,
   means sufficient torque is detected to move forward or downhill is detected.
   The release gradient shall also be useful for comfort release since anyway the brake request release
   shall feel comfortable. So the standard drive off ramp shall also be able to fullfill comfort release */

CSM_PT1_AActProp.calc(AActProp,CycleTime,C_CSM_DriveOffAActPropTimeConstantTrqSuff,true);
AActProp_filt = CSM_PT1_AActProp.filtered_value();

// Get gradient of propulsive force
AActPropDelta = (AActProp_filt - AActPropfiltK1);
JActProp = AActPropDelta/CycleTime;

// Freeze of slope signal
if(	   (	VehStop      == true
		&&	CsmHoldState == CSMHoldState_BrkInc)
	|| (	CsmHoldComfortReleaseActive == true
		&&	VehStop                     == true
		&&	CsmHoldState                == CSMHoldState_DriveOff)
	|| CsmHoldState == CSMHoldState_NotActive
	|| CsmHoldState == CSMHoldState_RollPrev
	|| CsmHoldState == CSMHoldState_BrkHold)
{
	// In case neutral gear is selected a release should be considered, like downhill
	// because the vehicle will move downhill
	if(VehMovDirGear == CSMVehMovDir_Undefined)
	{
		ASlopeFreezed = -(ASlopeGear.abs());
	}
	else
	{
		ASlopeFreezed = ASlopeGear;
	}
}


// Determine equilibrium value
if(VehMovDirGear == CSMVehMovDir_Undefined)
{
	ABrakeEq = -((ASlopeFreezed).abs());
}
else
{
	ABrakeEq = -((ASlopeFreezed - ((AActProp.max(0)).min(ASlopeFreezed.max(0)))).abs());
}
// Allow modification of equilibrium value
ABrakeEq = ABrakeEq * C_CSM_DriveOffABrakeEqSensFac.getAt(ASlopeFreezed)-C_CSM_DriveOffABrakeEqOffset.getAt(ASlopeFreezed);

// Determin acceleration request
AAccelReq = (AActProp.max(0)) - (ASlopeFreezed.max(0));


// if Drive Off triggered consider release ramp calculations
if(CsmHoldDriveReqActive > 0)
{
	// Reset of timers in case 
	if(		CsmHoldDrvOffTrqSuffActive == false							 // drive off is not active
		||	CsmHoldDriveOffTrqBalActiveK1 == true						 // or torque balanced has drive off
		|| (CsmHoldDriveReqActive >= 2 && CsmHoldBrkHoldActive == true)) // or a new drive off is requested while hold was still active
	{
		TimeSinceVCtrlRamp = 0;
		TimeSinceFullRamp = 0;
		TimeSinceRelease = 0;
		CsmHoldDriveOffATarBrk = CsmHoldATarBrk;
	}
	// In case there is a drive gear selected then 
	// or there is no possibility to detect neutral gear (then it shall always considered to be a gear selected)
	if(VehMovDirGear != CSMVehMovDir_Undefined)
	{
		// Determine release time to reach equlibrium state
		CsmDriveOffTimeConstantToEq = C_CSM_DriveOffTimeConstantToEq.getAt(AAccelReq,ASlopeFreezed);
		// Determine release time from equilibrium to full release
		CsmDriveOffTimeConstantToFullRel = C_CSM_DriveOffTimeConstantToFullRel.getAt(AAccelReq,ASlopeFreezed);
		// Manipulation of timer due to dependency on increase gradient of propulsive force
		CsmDriveOffFactor = C_CSM_DriveOffRelFactor.getAt(JActProp);
		CsmDriveOffTimeConstantToFullRel = CsmDriveOffTimeConstantToFullRel * CsmDriveOffFactor;	
	}
	else
	{
		// Determine release time to reach equlibrium state
		CsmDriveOffTimeConstantToEq = C_CSM_DriveOffTimeConstantToEq.getAt(0,ASlopeFreezed);
		// Determine release time from equilibrium to full release
		CsmDriveOffTimeConstantToFullRel = C_CSM_DriveOffTimeConstantToFullRel.getAt(0,ASlopeFreezed);
	}
	
	// Determine release ramp for target deceleration of speed controllers
	CsmDriveOffTimeConstantToFullRelVCtrl = C_CSM_DriveOffTimeConstantToFullRelVCtrl.getAt(CsmHoldCfgDrvOffATar,ASlopeFreezed);
	
	// Additionally modify the release time in case backward gear is selected
	if(VehMovDirGear == CSMVehMovDir_Backward)
	{
		CsmDriveOffTimeConstantToFullRel = CsmDriveOffTimeConstantToFullRel * C_CSM_DriveOffRGearFac;
		CsmDriveOffTimeConstantToFullRelVCtrl = CsmDriveOffTimeConstantToFullRelVCtrl * C_CSM_DriveOffRGearFac;
	}
	

	
	
	// As long as target brake request is higher than equilibrium, consider timing ramp to reach equlibrium
	if(CsmHoldATarBrk.abs() > ABrakeEq.abs())
	{
		CsmjDriveOff = ((CsmHoldATarBrk.abs()- ABrakeEq.abs()) / ((CsmDriveOffTimeConstantToEq - TimeSinceRelease - TimeInReleaseState).max(CycleTime)));
		CsmjDriveOff = (CsmjDriveOff.min(C_CSM_DriveOffjMax)).max(C_CSM_DriveOffjMin);
	}
	// else in case full release ramp is already triggered
	else
	{
		CsmjDriveOff = (CsmHoldATarBrk.abs() / ((CsmDriveOffTimeConstantToFullRel + TimeSinceVCtrlRamp - TimeSinceFullRamp - TimeInReleaseState).max(CycleTime)));
		CsmjDriveOff = (CsmjDriveOff.min(C_CSM_DriveOffjMax)).max(C_CSM_DriveOffjMin);
			
		// in case speed controller is asking for some specific vehicle acceleration, release ramp should be reduced
		// only allowed in case no accelerator pedal is pressed by the driver
		if(		MotPedalPosDrvOrFcn  < C_CSM_DriveOffMotPedalDriverApplied
			&&	CsmHoldCfgDrvOffATar > 0
			&&	CsmDriveOffTimeConstantToFullRelVCtrl > CsmDriveOffTimeConstantToFullRel)
		{
			CsmjDriveOff = CsmjDriveOff.min(CsmHoldATarBrk.abs() / ((CsmDriveOffTimeConstantToFullRelVCtrl - TimeSinceVCtrlRamp - TimeInReleaseState).max(CycleTime)));
			CsmjDriveOff = (CsmjDriveOff.min(C_CSM_DriveOffjMax)).max(C_CSM_DriveOffjMinVTar);

			TimeSinceVCtrlRamp = TimeSinceVCtrlRamp + CycleTime + TimeInReleaseState;
		}
		
		TimeSinceFullRamp = TimeSinceFullRamp + CycleTime + TimeInReleaseState;
	}
	
	TimeSinceRelease = TimeSinceRelease + CycleTime + TimeInReleaseState;
	
	// In case the timer since the release phase is too high a more fast release shall be triggered to bring the vehicle to movement
	if(TimeSinceRelease >= C_CSM_DriveOffTrqSuffMaxTime && VehStop == true && FS_CSM_DriveOffEnableTimeToMove)
	{
		CsmjDriveOff = CsmjDriveOff.max(CsmHoldATarBrk.abs() / ((C_CSM_DriveOffTrqSuffMaxTime + C_CSM_DriveOffTime2FullRel - TimeSinceRelease).max(CycleTime)));
		CsmjDriveOff = (CsmjDriveOff.min(C_CSM_DriveOffjMax)).max(C_CSM_DriveOffjMin);
	}
	
	
	if(DrvOffTrqSufficient == true && CsmHoldDriveOffATarBrk < 0)
	{
		CsmHoldDrvOffTrqSuffActive = true;
		CsmHoldDriveOffATarBrk = (CsmHoldDriveOffATarBrk + CsmjDriveOff * CycleTime).min(0);
		CsmHoldDrvOffEnableReactByBrkInc = false;
	}else if(	(CsmHoldDrvOffTrqSuffActive == true && CsmHoldDriveOffATarBrk < 0)
			||	(CsmHoldComfortReleaseActive == true && CsmHoldDriveOffATarBrk < 0)
			||	(CsmHoldState == CSMHoldState_Deact && CsmHoldDriveOffATarBrk < 0)
			||	(CsmHoldDriveOffTrqBalActiveK1 == true && CsmHoldDriveOffATarBrk < 0))
	{
		// prototype CsmHoldDrvOffEnableReactByBrkInc = true;
		if(		CsmHoldATarBrk > ABrakeEq
			&&	CsmHoldDriveOffATarBrk > ABrakeEq
			&&	CsmHoldDriveOffATarBrk > CsmHoldATarThermLimit // only enable increase as long as thermal limit is not reached yet
			&&	CsmHoldRolloutReq != CSMRolloutReq_Off) // ------> fix. only enable inc support if rollout is requested in parallel
		{
			CsmHoldDrvOffEnableReactByBrkInc = true;
			CsmHoldDriveOffATarBrk = CsmHoldATarBrk.min(0); //------> fix.
		}else
		{
			CsmHoldDrvOffEnableReactByBrkInc = false;
			CsmHoldDriveOffATarBrk = (CsmHoldDriveOffATarBrk + CsmjDriveOff * CycleTime).min(0);
		}
		CsmHoldDrvOffTrqSuffActive = true;
		
	}else
	{
		// prototype CsmHoldDrvOffEnableReactByBrkInc = true;
		if(		CsmHoldATarBrk > ABrakeEq
			&&	CsmHoldDriveOffATarBrk > ABrakeEq
			&&	CsmHoldDriveOffATarBrk > CsmHoldATarThermLimit // only enable increase as long as thermal limit is not reached yet
			&&	CsmHoldRolloutReq != CSMRolloutReq_Off) // ------> fix. only enable inc support if rollout is requested in parallel
		{
			CsmHoldDrvOffEnableReactByBrkInc = true;
		}else
		{
			CsmHoldDrvOffEnableReactByBrkInc = false;
		}
		CsmHoldDrvOffTrqSuffActive = false;
		CsmHoldDriveOffATarBrk = 0;
	}
	
	// Reset of timers in case there is no drive off triggered anymore
	if(CsmHoldDrvOffTrqSuffActive == false)
	{
		TimeSinceVCtrlRamp = 0;
		TimeSinceFullRamp = 0;
		TimeSinceRelease = 0;
		CsmHoldDriveOffATarBrk = 0;
	}else if(CsmHoldDriveOffATarBrk > CsmHoldComfortReleaseATarBrk)
	{
		TimeSinceVCtrlRamp = 0;
		TimeSinceFullRamp = 0;
		TimeSinceRelease = 0;
		CsmHoldDriveOffATarBrk = CsmHoldComfortReleaseATarBrk;
	}
	
	TimeInReleaseState = 0;
}
// reset of release
else
{
	CsmHoldDrvOffTrqSuffActive = false;
	CsmHoldDrvOffEnableReactByBrkInc = true;
	CsmjDriveOff = 15000;
	CsmHoldDriveOffATarBrk = 0;
	TimeSinceVCtrlRamp = 0;
	TimeSinceFullRamp = 0;
	TimeSinceRelease = 0;
	if(CsmHoldState == CSMHoldState_Deact)
	{
		TimeInReleaseState = TimeInReleaseState + CycleTime;
	}else
	{
		TimeInReleaseState = 0;
	}
}

AActPropK1 = AActProp;
AActPropfiltK1 = AActProp_filt;


=== Method: CsmHoldDriveOffATarBrk (AbstractMethod) ===
return CsmHoldDriveOffATarBrk;


=== Method: CsmHoldDrvOffEnableReactByBrkInc (AbstractMethod) ===
return CsmHoldDrvOffEnableReactByBrkInc;


=== Method: CsmHoldDrvOffTrqSuffActive (AbstractMethod) ===
return CsmHoldDrvOffTrqSuffActive;
